def solve_batch(study):
    """Blend sparse two-mode predictions with a calibrated ridge readout."""
    sparse = _sparse(study)
    panel = _panel_pred(study, 1.0, 0.3, 'sat')
    y = 0.5 * sparse['y_hat'] + 0.5 * panel[:, 0]
